SELECT /* getActiveOwnerCnt */
       COUNT(*)
  FROM TM_CLUBXM CLUB
  JOIN TB_CLMEMX MEMBER
    ON MEMBER.CLUB_NUMB = CLUB.CLUB_NUMB
   AND MEMBER.USER_NUMB = CLUB.OWNR_NUMB
   AND MEMBER.MEMB_ROLE = #{ownerRole}
   AND MEMBER.MEMB_STAT = #{memberActive}
  JOIN TM_USERXM USERX
    ON USERX.USER_NUMB = CLUB.OWNR_NUMB
   AND USERX.USER_STAT = #{userActive}
 WHERE CLUB.CLUB_NUMB = #{clubNumb}
   AND CLUB.OWNR_NUMB = #{userNumb}
   AND CLUB.CLUB_STAT = #{clubActive}

