INSERT /* setReadingRound */ INTO TM_CLRNDX (
            CLUB_NUMB
          , ROND_NUMB
          , BOOK_NUMB
          , ROND_STAT
          , GOAL_STDT
          , GOAL_ENDT
          , OPEN_DATE
          , IDEM_KEYX
          , REGI_USER
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{clubNumb}
          , #{request.rondNumb}
          , #{request.bookNumb}
          , CASE WHEN #{request.goalStdt} <= CURRENT_DATE THEN #{roundReading}
                 ELSE #{roundScheduled}
            END
          , #{request.goalStdt}
          , #{request.goalEndt}
          , CASE WHEN #{request.goalStdt} <= CURRENT_DATE THEN CURRENT_TIMESTAMP(6)
                 ELSE NULL
            END
          , #{request.idemKeyx}
          , #{userNumb}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)


