UPDATE /* uptClub */ TM_CLUBXM
   SET CLUB_NAME = #{request.clubName}
     , CLUB_CNTN = #{request.clubCntn}
     , CLUB_VISB = #{request.clubVisb}
     , JOIN_TYPE = #{request.joinType}
     , MAXX_MEMB = #{request.maxxMemb}
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND OWNR_NUMB = #{userNumb}
   AND CLUB_STAT = #{clubActive}
   AND EXISTS (
       SELECT 1
         FROM TM_USERXM USERX
        WHERE USERX.USER_NUMB = #{userNumb}
          AND USERX.USER_STAT = #{userActive}
   )

