       TB_CLMEMX
   SET MEMB_STAT = #{memberActive}
     , SEND_NUMB = NULL
     , INVT_DATE = NULL
     , EXPR_DATE = NULL
     , JOIN_DATE = CURRENT_TIMESTAMP(6)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}
   AND MEMB_STAT = #{memberInvited}
   AND EXPR_DATE > CURRENT_TIMESTAMP(6)

